</code></pre> <pre><code>const response = await fetch("https://api.docverify.dev/v1/verify/stream", {
  method: "POST",
  headers: {
    "Authorization": "Bearer dv_your_api_key",
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    source: "The agreement has a 24-month term with 60 days termination notice.",
    ai_output: "The contract lasts 36 months and requires 90 days notice.",
    domain: "legal",
  }),
});

const reader = response.body!.getReader();
const decoder = new TextDecoder();

while (true) {
  const { done, value } = await reader.read();
  if (done) break;

  const text = decoder.decode(value);
  for (const line of text.split("\n")) {
    if (line.startsWith("data: ")) {
      const data = JSON.parse(line.slice(6));
      console.log(data);
    }
  }
}
</code></pre>
